1	// AssistantEngine —— 语音搜索 / AI 搜索的统一引擎（真链路 + 可运行模拟链路）
2	//
3	// 官方链路（真机）：手表快应用 @system.interconnect ←→ 手机 App（xms-wearable SDK）
4	//   const conn = interconnect.instance()
5	//   conn.onmessage = (data) => {...}     // 收手机数据
6	//   conn.send({ data: 'xxx' })          // 发到手机
7	//   conn.getReadyState({...})           // 查连接状态
8	//   ⚠️ 约束：需配套手机 App、两端证书一致（官方 FAQ：通信前检查签名）。
9	//
10	// 模拟链路（模拟器/无手机对端）：interconnect 不可用或未就绪时自动启用。
11	//   设计原则：只有「声学识别 / 云端大模型」被替换为本地模拟源，
12	//   其余全部真实运行 —— 识别结果会真实填入搜索框并触发本地搜索引擎；
13	//   AI 回答由本地检索 + 模板摘要真实生成，绝非写死的假文案。
14	//
15	// 依赖：零（纯 ES5；interconnect 按需 require，失败即走模拟）
16	
17	var MODE = {
18	  REAL: 'real',        // 真机：interconnect 通道（手机 App 应答）
19	  SIM: 'sim'           // 模拟：本地模拟源（模拟器演示 / 无对端）
20	}
21	
22	var SIM_LATENCY = 1500          // 模拟识别延迟（ms）：贴近真实语音识别耗时
23	var SIM_AI_LATENCY = 900        // 模拟 AI 思考延迟（ms）
24	
25	// —— 同义词扩展（本地问答理解）：把口语问题映射到资料库词 ——
26	var SYNONYMS = [
27	  [/(怎么|如何|怎样).*(急救|救急|处理)/, '急救'],
28	  [/(怎么|如何|怎样).*(感冒|发烧|发热)/, '感冒'],
29	  [/(怎么|如何|怎样).*(入睡|失眠|睡不着)/, '睡眠'],
30	  [/(减肥|瘦身)/, '运动'],
31	  [/(背单词|记单词|学英语)/, '记忆'],
32	  [/(血压|血糖)/, '血压'],
33	  [/(做菜|做饭|烹饪)/, '烹饪'],
34	  [/(养花|浇花|绿植)/, '绿植'],
35	  [/(省钱|理财|存钱)/, '理财'],
36	  [/(带孩子|育儿|宝宝)/, '育儿']
37	]
38	
39	function Assistant() {
40	  this.mode = null
41	  this.conn = null
42	  this._voiceCb = null
43	  this._aiCb = null
44	  this._simTimer = null
45	  this._probeDone = false
46	}
47	
48	// 探测通道：真链路优先（interconnect 就绪），否则模拟。结果缓存（连接状态变化时 reprobe）。
49	Assistant.prototype.probe = function (onReady) {
50	  var self = this
51	  if (this._probeDone && this.mode) { onReady(this.mode); return }
52	  try {
53	    var interconnect = require('@system.interconnect')
54	    var conn = interconnect.instance()
55	    conn.getReadyState({
56	      success: function (data) {
57	        if (data && data.status === 1) {
58	          self.mode = MODE.REAL
59	          self.conn = conn
60	          self._bindReal(conn)
61	        } else {
62	          self.mode = MODE.SIM
63	        }
64	        self._probeDone = true
65	        onReady(self.mode)
66	      },
67	      fail: function () {
68	        self.mode = MODE.SIM
69	        self._probeDone = true
70	        onReady(self.mode)
71	      }
72	    })
73	  } catch (e) {
74	    // 模拟器上 interconnect 通常不可 require 或无对端 → 模拟链路
75	    this.mode = MODE.SIM
76	    this._probeDone = true
77	    onReady(this.mode)
78	  }
79	}
80	
81	// 绑定真链路消息（手机 App 的应答）
82	// ⚠️ 包装链（审查修复）：BtTransfer（蓝牙资料接收）也在这条通道设 conn.onmessage，
83	// 直接赋值会互相覆盖。保留原 handler，非本模块消息转发过去，两模块都能收到。
84	Assistant.prototype._bindReal = function (conn) {
85	  var self = this
86	  var prevHandler = conn.onmessage
87	  conn.onmessage = function (data) {
88	    var handled = false
89	    if (data && data.data) {
90	      var msg = null
91	      try { msg = JSON.parse(data.data) } catch (e) { msg = null }
92	      if (msg && msg.type === 'voice_result' && self._voiceCb) {
93	        self._voiceCb({ ok: true, text: msg.text || '', mode: MODE.REAL })
94	        handled = true
95	      } else if (msg && msg.type === 'ai_result' && self._aiCb) {
96	        self._aiCb({ ok: true, answer: msg.answer || '', results: msg.results || [], mode: MODE.REAL })
97	        handled = true
98	      }
99	    }
100	    if (!handled && typeof prevHandler === 'function') {
101	      try { prevHandler(data) } catch (e) {}
102	    }
103	  }
104	}
105	
106	// ============ 语音搜索 ============
107	// 真链路：向手机发送语音搜索请求（手机端做 ASR 后回传文本）
108	// 模拟链路：从资料集高频词中抽一个词作为"识别结果"（延迟 SIM_LATENCY），
109	//          走与真链路完全相同的回调 —— 后续填词/搜索/出结果全部真实执行。
110	Assistant.prototype.recognize = function (cb) {
111	  var self = this
112	  this._voiceCb = cb
113	  this.cancelSim()
114	  this.probe(function (mode) {
115	    if (mode === MODE.REAL) {
116	      try {
117	        self.conn.send({ data: JSON.stringify({ type: 'voice_search' }) })
118	      } catch (e) {
119	        // 真链路发送失败 → 降级模拟（保证任何环境都能跑完流程）
120	        self._simVoice(cb)
121	      }
122	    } else {
123	      self._simVoice(cb)
124	    }
125	  })
126	}
127	
128	Assistant.prototype._simVoice = function (cb) {
129	  var self = this
130	  var word = this._pickSimWord()
131	  this._simTimer = setTimeout(function () {
132	    self._simTimer = null
133	    cb({ ok: !!word, text: word, mode: MODE.SIM })
134	  }, SIM_LATENCY)
135	}
136	
137	// ============ AI 搜索 ============
138	// 真链路：把问题发到手机 App（云端大模型应答）
139	// 模拟链路：本地"问答理解"（同义词归一）→ 真实搜索引擎检索 → 模板摘要生成回答。
140	//          回答内容由检索结果真实拼出，问题不同则回答不同，非固定文案。
141	Assistant.prototype.answer = function (question, searchFn, cb) {
142	  var self = this
143	  this._aiCb = cb
144	  this.cancelSim()
145	  this.probe(function (mode) {
146	    if (mode === MODE.REAL) {
147	      try {
148	        self.conn.send({ data: JSON.stringify({ type: 'ai_search', q: question }) })
149	      } catch (e) {
150	        self._simAI(question, searchFn, cb)
151	      }
152	    } else {
153	      self._simAI(question, searchFn, cb)
154	    }
155	  })
156	}
157	
158	Assistant.prototype._simAI = function (question, searchFn, cb) {
159	  var self = this
160	  var keyword = this._understand(question)
161	  if (!keyword) { cb({ ok: false, reason: 'empty' }); return }
162	  var t0 = Date.now()
163	  searchFn(keyword).then(function (result) {
164	    var items = (result && result.results) || []
165	    var total = (result && result.total) || 0
166	    // 摘要生成：由检索结果真实拼出（取前 2 条的标题与正文首句）
167	    var lines = []
168	    var upper = items.length < 2 ? items.length : 2
169	    for (var i = 0; i < upper; i++) {
170	      var it = items[i]
171	      var first = (it.title || '').split(/[，。,.]/)[0]
172	      lines.push((i + 1) + '. ' + first)
173	    }
174	    var answer = lines.length
175	      ? ('关于「' + keyword + '」，共找到 ' + total + ' 条资料：' + lines.join('；') + '。')
176	      : ('本地资料中未找到与「' + keyword + '」直接相关的内容，换个说法试试？')
177	    // 保证回答至少延迟 SIM_AI_LATENCY（模拟"思考"节奏），检索更快则补齐
178	    var wait = Math.max(0, SIM_AI_LATENCY - (Date.now() - t0))
179	    setTimeout(function () { cb({ ok: true, answer: answer, keyword: keyword, results: items, total: total, mode: MODE.SIM }) }, wait)
180	  }).catch(function () {
181	    cb({ ok: false, reason: 'search_error' })
182	  })
183	}
184	
185	// 本地问答理解：同义词归一 → 抽取 2 字以上中文词 / 英文词（最长者优先）
186	Assistant.prototype._understand = function (q) {
187	  var s = String(q || '').trim()
188	  if (!s) return ''
189	  for (var i = 0; i < SYNONYMS.length; i++) {
190	    if (SYNONYMS[i][0].test(s)) return SYNONYMS[i][1]
191	  }
192	  var m = s.match(/[a-zA-Z]{3,}/)
193	  if (m) return m[0].toLowerCase()
194	  m = s.match(/[\u4e00-\u9fa5]{2,}/g)
195	  if (m && m.length) {
196	    var best = ''
197	    for (var j = 0; j < m.length; j++) { if (m[j].length > best.length) best = m[j] }
198	    return best
199	  }
200	  return s
201	}
202	
203	// 模拟语音识别的"结果词"：从内置高频演示词表抽取（均来自资料集真实标题词，保证必命中）
204	Assistant.prototype._pickSimWord = function () {
205	  var words = ['感冒', '急救', '睡眠', '唐朝', '唐朝', '运动', '早餐', '绿植', '理财', '记忆', '秦', '宋朝']
206	  return words[Math.floor(Math.random() * words.length)]
207	}
208	
209	Assistant.prototype.cancelSim = function () {
210	  if (this._simTimer) {
211	    clearTimeout(this._simTimer)
212	    this._simTimer = null
213	  }
214	}
215	
216	Assistant.prototype.cancel = function () {
217	  this.cancelSim()
218	  this._voiceCb = null
219	  this._aiCb = null
220	}
221	
222	Assistant.prototype.getMode = function () { return this.mode || MODE.SIM }
223	
224	// —— 单例 ——
225	var _instance = null
226	function getAssistant() {
227	  if (!_instance) _instance = new Assistant()
228	  return _instance
229	}
230	
231	export { getAssistant }   // MODE 仅引擎内部使用，未导出（2026-09-17 审查清理死导出）
