9	  // ========== 日志系统（直接操作 storage）==========
10	  var LOG_KEY = 'app_runtime_logs'
11	  var MAX_LOGS = 30
12	  var logQueue = []
13	
14	  // 导入 storage（注意：需要在函数内部 require）
15	  function getStorage() {
16	    return require('@system.storage')
17	  }
18	
19	  // 保存日志到 storage
20	  function saveLogsToStorage() {
21	    try {
22	      var storage = getStorage()
23	      storage.set({
24	        key: LOG_KEY,
25	        value: JSON.stringify(logQueue.slice(0, MAX_LOGS))
26	      })
27	    } catch(e) {
28	      console.log('日志保存失败:', e)
29	    }
30	  }
31	
32	  // 加载已有日志
33	  function loadLogsFromStorage() {
34	    try {
35	      var storage = getStorage()
36	      storage.get({
37	        key: LOG_KEY,
38	        success: function(data) {
39	          try {
40	            var saved = JSON.parse(data)
41	            if (saved && saved.length) {
42	              logQueue = saved
