54	  // 手写补零（避免 padStart 的轻量运行时兼容风险——见 CC_BRIEF 已知坑 #5）
55	  function pad2(n) {
56	    return n < 10 ? '0' + n : '' + n
57	  }
58	
59	  // 添加日志
60	  var logSaveTimer = null
61	  global.addRuntimeLog = function(msg, level) {
62	    var now = new Date()
63	    var time = pad2(now.getHours()) + ':' + pad2(now.getMinutes()) + ':' + pad2(now.getSeconds())
64	
65	    logQueue.unshift({
66	      time: time,
67	      msg: msg,
68	      level: level || 'info'
69	    })
70	
71	    if (logQueue.length > MAX_LOGS) {
72	      logQueue.pop()
73	    }
74	
75	    // ⚠️ 合并写入（v1.16.32 性能修复）：原先每条日志都立即 storage.set，
