302	      // ——此处只记无效标志，onShow 再执行返回
303	      this._invalidTarget = (!target && target !== 0)
304	      if (this._invalidTarget) return
305	      this.dsId = target
306	      var info = (typeof global.getDatasetInfo === 'function') ? global.getDatasetInfo(target) : null
307	      if (!info) { this._invalidTarget = true; return }
308	      this.dsName = info.name
309	      this.dsDesc = info.desc || ''
310	      this.dsIcon = info.icon
311	      this.dsIconClass = 'ds-icon-box ' + (info.colorClass || 'ci-ds')
312	      this.dsCount = (info.count !== undefined) ? info.count : -1
313	      var tags = []
314	      for (var i = 0; i < info.tags.length; i++) {
315	        tags.push({ label: info.tags[i].label, value: info.tags[i].value, cls: 'ds-tag' })
316	      }
317	      this.dsTags = tags
318	      // 屏幕形态（键盘组件所需）
319	      var self = this
320	        device.getInfo({
321	          success: function(data) {
322	            var shape = data.screenShape
323	            self.screentype = shape === 'circle' ? 'circle' : (shape === 'pill-shaped' ? 'pill-shaped' : 'rect')
