333	    onShow() {
334	      var self = this
335	      // 审查中#3：onInit 记录的无效目标在这里退（onInit 阶段 router 静默失效）
336	      if (this._invalidTarget) { router.back(); return }
337	      // 审查中#4：onShow 每次都 new interval 会泄漏（从详情页返回一次多一个）——先清旧的
338	      if (this.timeTimer) { clearInterval(this.timeTimer); this.timeTimer = null }
339	      this.updateTime()
340	      this.timeTimer = setInterval(function() { self.updateTime() }, 30000)
341	    },
